create policy marketplace_payment_events_deny_authenticated on public.marketplace_payment_events for select to authenticated using(false);
revoke execute on function public.is_marketplace_admin() from authenticated;
drop policy if exists marketplace_moderation_admin_read on public.marketplace_moderation_cases;drop policy if exists marketplace_moderation_admin_update on public.marketplace_moderation_cases;drop policy if exists marketplace_disputes_admin_read on public.marketplace_disputes;drop policy if exists marketplace_disputes_admin_update on public.marketplace_disputes;
create policy marketplace_moderation_admin_read on public.marketplace_moderation_cases for select to authenticated using(exists(select 1 from public.marketplace_admins a where a.user_id=(select auth.uid())));
create policy marketplace_moderation_admin_update on public.marketplace_moderation_cases for update to authenticated using(exists(select 1 from public.marketplace_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.marketplace_admins a where a.user_id=(select auth.uid())));
create policy marketplace_disputes_admin_read on public.marketplace_disputes for select to authenticated using(exists(select 1 from public.marketplace_admins a where a.user_id=(select auth.uid())));
create policy marketplace_disputes_admin_update on public.marketplace_disputes for update to authenticated using(exists(select 1 from public.marketplace_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.marketplace_admins a where a.user_id=(select auth.uid())));